/* Focused category maintenance over the shared record catalogue. */
let recordManagedCategory='',recordCategoryEdit='';
function recordManagedCategories(){return state.itemCategories.filter(c=>!c.parentId&&!['category-shared-configuration','health-source-medicines'].includes(c.id)&&!/vaccin/i.test(c.name)&&!modules.includes(c.name));}
function recordManagedCategoryIds(id){return id==='cat-health-medicines'?['cat-health-medicines','health-source-medicines']:[id];}
function recordChooseManagedCategory(id){recordManagedCategory=id;recordCategoryEdit='';recordManageCategories();}
function recordEditManagedCategory(id){recordCategoryEdit=id;recordManageCategories();}
function recordBeginSubcategory(){recordCategoryEdit='new';recordManageCategories();}
function recordCategoryManagerBack(){recordCategoryEdit='';renderItems();}
recordManageCategories=function(){
 if(!canEdit())return;
 ensureRecordWorkspace();closeModal();document.body.classList.remove('config-workspace-focused');
 const categories=recordManagedCategories();let selected=categories.find(c=>c.id===recordManagedCategory)||categories.find(c=>!c.archived)||categories[0];recordManagedCategory=selected?.id||'';
 const children=selected?state.itemCategories.filter(c=>recordManagedCategoryIds(selected.id).includes(c.parentId)):[];
 const status=c=>`<span class="status-pill ${c.archived?'archived':'active'}">${c.archived?'Archived':'Active'}</span>`;
 const edit=c=>`<form class="category-focused-form" onsubmit="event.preventDefault();recordRenameCategory('${c.id}')"><label>${c.parentId?'Subcategory':'Category'} name<input id="record-rename-${c.id}" required maxlength="120" value="${esc(c.name)}" autofocus></label><div><button type="button" onclick="recordEditManagedCategory('')">Cancel</button><button class="primary" type="submit">Save name</button></div></form>`;
 $('#main').innerHTML=`<section class="category-manager-page"><div class="category-manager-heading"><button class="category-back" onclick="recordCategoryManagerBack()">← Business records</button><h1>Categories</h1></div><div class="category-manager-layout"><nav class="category-manager-nav" aria-label="Manage record categories">${categories.map(c=>`<button class="${c.id===selected?.id?'selected':''}" onclick="recordChooseManagedCategory('${c.id}')" ${c.id===selected?.id?'aria-current="true"':''}><span>${esc(c.name)}</span><small>${c.archived?'Archived':((n)=>n+' '+(n===1?'subcategory':'subcategories'))(state.itemCategories.filter(s=>recordManagedCategoryIds(c.id).includes(s.parentId)&&!s.archived).length)}</small></button>`).join('')}</nav><section class="category-manager-detail">${selected?`<div class="category-manager-title"><div><span class="eyebrow">Category</span><h2>${esc(selected.name)}</h2>${status(selected)}</div><div class="actions"><button onclick="recordEditManagedCategory('${selected.id}')">Rename</button><button onclick="recordArchiveCategory('${selected.id}')">${selected.archived?'Restore':'Archive'}</button></div></div>${recordCategoryEdit===selected.id?edit(selected):''}<div class="category-subheading"><h3>Subcategories</h3><button onclick="recordBeginSubcategory()" ${selected.archived?'disabled':''}>+ Subcategory</button></div>${recordCategoryEdit==='new'?`<form class="category-focused-form" onsubmit="event.preventDefault();recordAddSubcategory('${selected.id}')"><label>Subcategory name<input id="record-add-sub-${selected.id}" required maxlength="120" autofocus></label><div><button type="button" onclick="recordEditManagedCategory('')">Cancel</button><button class="primary" type="submit">Add subcategory</button></div></form>`:''}<div class="category-table-scroll"><table class="category-subtable"><thead><tr><th>Name</th><th>Status</th><th>Actions</th></tr></thead><tbody>${children.map(c=>`<tr><td>${esc(c.name)}</td><td>${status(c)}</td><td><div class="actions"><button onclick="recordEditManagedCategory('${c.id}')" aria-label="Rename ${esc(c.name)}">Edit</button><button onclick="recordArchiveCategory('${c.id}')" ${selected.archived&&c.archived?'disabled':''}>${c.archived?'Restore':'Archive'}</button></div></td></tr>${recordCategoryEdit===c.id?`<tr><td colspan="3">${edit(c)}</td></tr>`:''}`).join('')||'<tr><td colspan="3" class="category-empty">No subcategories yet.</td></tr>'}</tbody></table></div>`:'<div class="category-empty">Create a category from Business records to get started.</div>'}<p id="record-manage-error" class="error" role="alert" aria-live="polite"></p></section></div></section>`;
};
const recordCategoryManagerRename=recordRenameCategory,recordCategoryManagerArchive=recordArchiveCategory,recordCategoryManagerAdd=recordAddSubcategory;
recordRenameCategory=function(id){const previous=recordCategoryEdit;recordCategoryManagerRename(id);if(!$('#record-manage-error')?.textContent){recordCategoryEdit='';recordManageCategories();}else recordCategoryEdit=previous;};
recordArchiveCategory=function(id){recordCategoryManagerArchive(id);if(!$('#record-manage-error')?.textContent){recordCategoryEdit='';recordManageCategories();}};
recordAddSubcategory=function(id){if(itemCategory(id)?.archived){$('#record-manage-error').textContent='Restore this category before adding a subcategory.';return;}recordCategoryManagerAdd(id);if(!$('#record-manage-error')?.textContent){recordCategoryEdit='';recordManageCategories();}};
